function reverseAdjectiveOrder(sentence) {
  // Split the sentence into words using a space as a delimiter
  const words = sentence.split(' ');

  let currentIndex = -1; // Initialize index for traversing the array from the end
  let result = []; // Initialize empty array to store the reversed words

  // Loop through the words in reverse order
  for (let i = words.length - 1; i >= 0; i--) {
    const word = words[i]; // Get the current word

    // Check if the word is an adjective using a simple heuristic (you may want to use a library or more sophisticated method for part-of-speech tagging)
    if (isAdjective(word)) {
      currentIndex++; // Save the index where we will insert the adjective in the result array

      // Insert the adjective in the result array
      result.splice(currentIndex, 0, word);
    }
  }

  // Add remaining words (not checked for adjectives) to the result array
  result = result.concat(words.slice(0, currentIndex + 1));

  // Join the words in the result array back into a sentence
  return result.join(' ') + ' ' + words[words.length - 1]; // Add the last word without an adjective check
}

// Helper function to check if a word is an adjective based on a simple heuristic
function isAdjective(word) {
  // You can extend this list of common adjective suffixes or use a more sophisticated method like NLTK or spaCy
  const suffixes = ['able', 'al', 'ant', 'ative', 'ic', 'ish'];
  return word.length > 2 && suffixes.some(suffix => word.endsWith(suffix));
}
```
