// Configure Multer-GridFS storage engine
const storage = new GridFsStorage({
  url: 'mongodb://localhost:27017/myImageDatabase', // replace with your MongoDB connection string
  file: (req, file) => {
    return {
      filename: file.originalname,
      bucketName: 'images'
    };
