 Here's the code you can use to create a `RedisClient` class with the specified methods in Node.js using the `redis` package:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  async isAlive() {
    return new Promise((resolve, reject) => {
      this.client.ping((err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply === 'PONG');
        }
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          reject(err);
        } else {
          resolve(value);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { redisClient };
```

This code creates the `RedisClient` class with the required methods, initializes an instance of the class named `redisClient`, and exports it along with the class definition. The `RedisClient` constructor sets up an error event listener to log any errors to the console. Each method is defined as an asynchronous function

