 To identify if a given sentence in Go contains a double negative, follow these steps:

1. Create a slice of specific negative words.
2. Split the given sentence into individual words.
3. Iterate through each word in the sentence.
4. Check if the current word is in the slice of negative words or the phrase "not" followed by a negative word is present in the remaining part of the sentence.
5. If both conditions are satisfied, print a message indicating that the sentence contains a double negative.

Here's an example Go code snippet to accomplish this:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	// Slice of negative words
	negativeWords := []string{"isn't", "am not", "doesn't", "does not", "haven't", "have not", "aren't", "are not", "won't", "will not", "can't", "cannot", "couldn't", "could not"}

	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Fields(sentence) // Split the sentence into individual words
	doubleNegativeDetected := false

	for i, currentWord := range words {
		if containsNegativeWord(currentWord) || (i < len(words)-1 && (containsNegativeWord(words[i]) && words[i+1] == "not")) {
			doubleNegativeDetected = true
			break
		}
	}

	if doubleNegativeDetected {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func containsNegativeWord(word string) bool {
	for _, negativeWord := range negativeWords {
		if strings.Contains(word, negativeWord) {
			return true
		}
	}
	return false
}
```

